verificationScript:
param([ValidateSet('public','process')][string]$Kind)
$ErrorActionPreference='Stop'
$root=(Get-Location).Path
$inventoryPath=Join-Path $root '.lake/native1/claim-surface-paths.json'
$inventory=Get-Content -LiteralPath $inventoryPath -Raw | ConvertFrom-Json
foreach($pin in @($inventory.scanner,$inventory.policy)) {
  if((Get-FileHash -LiteralPath $pin.path).Hash -cne $pin.sha256){throw 'Claim scanner/policy bytes changed'}
}
$paths=[string[]]$(if($Kind -ceq 'public'){$inventory.publicPaths}else{$inventory.processPaths})
$expectedCount=if($Kind -ceq 'public'){44}else{26}
if($paths.Count -ne $expectedCount -or @($paths | Sort-Object -Unique).Count -ne $expectedCount){throw 'Exact claim path roster mismatch'}
$pins=@(foreach($path in $paths){@{path=$path;bytes=(Get-Item -LiteralPath $path).Length;sha256=(Get-FileHash -LiteralPath $path).Hash}})
$watch=[Diagnostics.Stopwatch]::StartNew()
$scanOutput=@(if($Kind -ceq 'public') { & scripts/claim_drift_scan.ps1 -Strict -Path $paths *>&1 } else { & scripts/claim_drift_scan.ps1 -Strict -IncludeProcessRecords -Path $paths *>&1 }) | ForEach-Object {$_.ToString()}
$code=$LASTEXITCODE
$watch.Stop()
foreach($pin in $pins){if((Get-FileHash -LiteralPath $pin.path).Hash -cne $pin.sha256){throw ('Claim input changed during scan: '+$pin.path)}}
[ordered]@{schema='native1-maintained-claims-v1';kind=$Kind;pass=($code -eq 0);exitCode=$code;checkedUtc=[DateTime]::UtcNow.ToString('o');durationSeconds=$watch.Elapsed.TotalSeconds;scanner=$inventory.scanner;policy=$inventory.policy;paths=$paths;sourcePins=$pins;inputsUnchanged=$true;output=$scanOutput;corpusInventory=$inventory;verificationScript=[IO.File]::ReadAllText($PSCommandPath)} |
  ConvertTo-Json -Depth 15 | Set-Content -LiteralPath ('docs/internal/extensions/native1/commands/final-claims-'+$Kind+'.json') -Encoding utf8
$scanOutput | Select-Object -Last 5 | Write-Output
Write-Output ('NATIVE1 CLAIMS '+$Kind+' exit='+$code+' seconds='+$watch.Elapsed.TotalSeconds)
exit $code
